    <td background="images/riga.gif"></td>
  </tr>
  <tr>
    <td background="images/bg.gif" align="center"><font class="content">Written by <a href="http://www.drownedmadonna.com/index.php">Giampiero</a> on 2005-06-15 14:53:04 W. Europe Standard Time  [53 reads].</font><br>
